class EventArgs:
    """Event data passed to handlers: X, Y, Button, Delta, KeyCode, KeyChar, Cancel."""

    def __init__(self, ev=None):
        self.raw = ev
        self.X = getattr(ev, "x", 0)
        self.Y = getattr(ev, "y", 0)
        num = getattr(ev, "num", 0)
        self.Button = num if isinstance(num, int) else 0
        self.Delta = getattr(ev, "delta", 0)
        self.KeyCode = getattr(ev, "keysym", "")
        self.KeyChar = getattr(ev, "char", "")
        self.Cancel = False


class _ToolTip:
    def __init__(self, widget, text):
        self.widget, self.text, self.tip = widget, text, None
        widget.bind("<Enter>", self.show, add="+")
        widget.bind("<Leave>", self.hide, add="+")

    def show(self, _e=None):
        if self.tip is not None:
            return
        x = self.widget.winfo_rootx() + 12
        y = self.widget.winfo_rooty() + self.widget.winfo_height() + 4
        self.tip = tw = tk.Toplevel(self.widget)
        tw.wm_overrideredirect(True)
        tw.wm_geometry(f"+{x}+{y}")
        tk.Label(tw, text=self.text, bg="#FFFFE1", relief="solid", bd=1,
                 font=("Segoe UI", 8)).pack()

    def hide(self, _e=None):
        if self.tip is not None:
            self.tip.destroy()
            self.tip = None


class _Timer:
    """VB-like Timer: set Interval (ms) and Enabled; calls tick() every Interval."""

    def __init__(self, root, interval, tick, enabled=False):
        self.root, self.Interval, self._tick, self._job = root, interval, tick, None
        self._enabled = False
        self.Enabled = enabled

    @property
    def Enabled(self):
        return self._enabled

    @Enabled.setter
    def Enabled(self, value):
        self._enabled = bool(value)
        if self._job is not None:
            self.root.after_cancel(self._job)
            self._job = None
        if self._enabled:
            self._job = self.root.after(max(1, int(self.Interval)), self._fire)

    def Start(self):
        self.Enabled = True

    def Stop(self):
        self.Enabled = False

    def _fire(self):
        self._job = None
        if self._enabled:
            self._job = self.root.after(max(1, int(self.Interval)), self._fire)
            self._tick()


def _set_enabled(widget, on=True):
    """Enable/disable a tk or ttk widget (or a container's children)."""
    try:
        widget.configure(state="normal" if on else "disabled")
        return
    except tk.TclError:
        pass
    try:
        widget.state(["!disabled"] if on else ["disabled"])
    except (tk.TclError, AttributeError):
        for child in widget.winfo_children():
            _set_enabled(child, on)


class _CommonDialog:
    """OpenFileDialog / SaveFileDialog / ColorDialog / FontDialog / FolderBrowserDialog.
    ShowDialog() returns "OK" or "Cancel" and fills FileName / Color / FontName, FontSize /
    SelectedPath. ShowOpen / ShowSave / ShowColor / ShowFont / ShowFolder work on any of them."""

    def __init__(self, root, kind, **props):
        self.root, self.Kind = root, kind
        self.Title, self.Filter, self.FileName, self.InitialDirectory = "", "All files|*.*", "", ""
        self.Color, self.FontName, self.FontSize, self.SelectedPath = "#000000", "Segoe UI", 9, ""
        for k, v in props.items():
            setattr(self, k, v)

    def ShowDialog(self):
        return {"open": self.ShowOpen, "save": self.ShowSave, "color": self.ShowColor,
                "font": self.ShowFont, "folder": self.ShowFolder}[self.Kind]()

    def _filetypes(self):
        parts = [p.strip() for p in str(self.Filter or "").split("|")]
        out = []
        for i in range(0, len(parts) - 1, 2):
            pats = tuple(x.strip() for x in parts[i + 1].split(";") if x.strip()) or ("*.*",)
            out.append((parts[i], pats if len(pats) > 1 else pats[0]))
        return out or [("All files", "*.*")]

    def _file_options(self):
        opts = {"parent": self.root, "filetypes": self._filetypes()}
        if self.Title:
            opts["title"] = self.Title
        folder = self.InitialDirectory or (os.path.dirname(self.FileName) if self.FileName else "")
        if folder:
            opts["initialdir"] = folder
        if self.FileName:
            opts["initialfile"] = os.path.basename(self.FileName)
        return opts

    def _done(self, prop, value):
        if not value:
            return "Cancel"
        setattr(self, prop, str(value))
        return "OK"

    def ShowOpen(self):
        from tkinter import filedialog
        return self._done("FileName", filedialog.askopenfilename(**self._file_options()))

    def ShowSave(self):
        from tkinter import filedialog
        opts = self._file_options()
        first = opts["filetypes"][0][1]
        first = first[0] if isinstance(first, tuple) else first
        if first.startswith("*.") and "*" not in first[2:]:
            opts["defaultextension"] = first[1:]
        return self._done("FileName", filedialog.asksaveasfilename(**opts))

    def ShowColor(self):
        from tkinter import colorchooser
        opts = {"parent": self.root, "title": self.Title or "Color"}
        if self.Color:
            opts["color"] = self.Color
        result = colorchooser.askcolor(**opts)
        return self._done("Color", result[1] if result else None)

    def ShowFolder(self):
        from tkinter import filedialog
        opts = {"parent": self.root, "mustexist": True}
        if self.Title:
            opts["title"] = self.Title
        if self.SelectedPath:
            opts["initialdir"] = self.SelectedPath
        return self._done("SelectedPath", filedialog.askdirectory(**opts))

    def ShowFont(self):
        result = _FontPicker(self.root, self.FontName, self.FontSize, self.Title or "Font").result
        if not result:
            return "Cancel"
        self.FontName, self.FontSize = result
        return "OK"


class _FontPicker:
    """A small modal font chooser (family list, size, preview)."""

    def __init__(self, root, family="Segoe UI", size=9, title="Font"):
        import tkinter.font as tkfont
        self.result = None
        top = self.top = tk.Toplevel(root)
        top.title(title)
        top.transient(root)
        top.resizable(False, False)
        families = sorted({f for f in tkfont.families(root) if not f.startswith("@")})
        self.family = tk.StringVar(value=family)
        self.size = tk.IntVar(value=int(size or 9))
        tk.Label(top, text="Font:").grid(row=0, column=0, sticky="w", padx=8, pady=(8, 0))
        tk.Label(top, text="Size:").grid(row=0, column=1, sticky="w", padx=8, pady=(8, 0))
        self.list = tk.Listbox(top, height=10, width=32, exportselection=False)
        for f in families:
            self.list.insert("end", f)
        self.list.grid(row=1, column=0, padx=8, sticky="nsew")
        tk.Spinbox(top, from_=4, to=96, width=5, textvariable=self.size,
                   command=self._preview).grid(row=1, column=1, padx=8, sticky="n")
        self.sample = tk.Label(top, text="AaBbYyZz 123", relief="groove", height=2)
        self.sample.grid(row=2, column=0, columnspan=2, padx=8, pady=8, sticky="ew")
        bar = tk.Frame(top)
        bar.grid(row=3, column=0, columnspan=2, sticky="e", padx=8, pady=(0, 8))
        tk.Button(bar, text="OK", width=9, command=self.ok).pack(side="left", padx=4)
        tk.Button(bar, text="Cancel", width=9, command=top.destroy).pack(side="left")
        if family in families:
            i = families.index(family)
            self.list.selection_set(i)
            self.list.see(i)
        self.list.bind("<<ListboxSelect>>", self._pick)
        top.bind("<Return>", lambda _e: self.ok())
        top.bind("<Escape>", lambda _e: top.destroy())
        self._preview()
        top.grab_set()
        top.wait_window()

    def _pick(self, _e=None):
        sel = self.list.curselection()
        if sel:
            self.family.set(self.list.get(sel[0]))
        self._preview()

    def _preview(self):
        try:
            self.sample.configure(font=(self.family.get(), int(self.size.get())))
        except (tk.TclError, ValueError):
            pass

    def ok(self):
        try:
            self.result = (self.family.get(), int(self.size.get()))
        except (tk.TclError, ValueError):
            self.result = None
        self.top.destroy()


